import { strict as assert } from "node:assert";
import { cpSync, mkdirSync, writeFileSync } from "node:fs";
import * as path from "node:path";
import { PiSession, resolvePiCli, startPiRun } from "./tests/harness-dock/pi-session.ts";
const run = startPiRun(resolvePiCli(process.env.FINAL_PI_CLI), "pi-three-consumer-final", { provider: "probe-provider", model: "gpt-4o-mini" });
const deployed = path.join(run.root.path, "deployment");
for (const folder of ["adapters", "framework", "extensions", "entrypoints"]) cpSync(path.resolve(folder), path.join(deployed, folder), { recursive: true });
const { symlinkSync } = await import("node:fs");
symlinkSync(path.resolve("node_modules"), path.join(deployed, "node_modules"), "junction");
let refusing = true;
const pushes = [];
const panel = Bun.serve({ hostname: "127.0.0.1", port: 0, async fetch(request) {
  const event = await request.json(); pushes.push(event);
  return refusing ? Response.json({ error: "refused fixture" }, { status: 503 }) : Response.json({ outcome: "registered", onlineCount: 1 });
}});
writeFileSync(path.join(deployed,"extensions/connect-bot/config.yaml"), `endpoint: http://127.0.0.1:${panel.port}\nrequestTimeoutMs: 1000\n`.replaceAll("\\n", "\n"));
writeFileSync(path.join(deployed,"extensions/model-cost/config.yaml"), `storageDir: '${path.join(run.root.path,"cost").replaceAll("\\","/")}'\nbalanceTtlMs: 30000\ncodexQuotaTtlMs: 15000\n`.replaceAll("\\n", "\n"));
let session;
let checks = 0;
function check(label, actual, expected) { assert.deepEqual(actual, expected, label); checks++; console.log("ok", label); }
async function notice(mark, message) { const frame = await session.frameSince(mark, f => f.type === "extension_ui_request" && f.method === "notify" && f.message === message, message, 5000); assert.ok(frame, message); checks++; console.log("ok", message); }
function area() { return [...session.frames()].reverse().find(f => f.type === "extension_ui_request" && f.method === "setWidget" && f.key === "semantic-extensions")?.content; }
try {
 session = await PiSession.start({ cli: run.cli, runRoot: run.root, entrypoint: ["codebase-tools","connect-bot","model-cost"].map(name => path.join(deployed,"entrypoints/pi",`${name}.ts`)), selector: run.selector });
 let mark = session.frameMark();
 check("codebase command handled without model", await session.run("/codebase-tools"), "handled");
 await notice(mark,"codeBaseTools enabled");
 check("only enabled codebase line",area(),["◈ codeBaseTools"]);
 mark = session.frameMark();
 await session.run("/connect-bot");
 await notice(mark,"无法连接 herdr-bot，未启用；请确认面板已启动");
 check("refusal leaves adjacent marker",area(),["◈ codeBaseTools"]);
 refusing = false;
 mark = session.frameMark();
 await session.run("/connect-bot");
 await notice(mark,"已接入 herdr-bot 面板（当前 1 个在线会话）");
 check("successful rearm composes two independent marker lines",area(),["◈ codeBaseTools","◐ connectBot"]);
 check("budget named action handled",await session.run("/budget detail"),"handled");
 const before=run.capture.requests().length;
 await session.run("one real combined-consumer exchange");
 check("one model request",run.capture.requests().length-before,1);
 const file=await session.sessionFile();
 const journal=session.journal(file);
 check("one persisted codebase init",journal.entries.filter(e=>e.type==="custom_message" && e.message?.customType==="codebase-tools:init").length,1);
 mark=session.frameMark();
 await session.run("/codebase-tools"); await notice(mark,"codeBaseTools disabled");
 check("codebase off preserves connected binding marker",area(),["◐ connectBot"]);
 mark=session.frameMark();
 await session.run("/connect-bot off"); await notice(mark,"已断开 herdr-bot 面板");
 check("both now off",area(),undefined);
 check("refused register and accepted rearm each attempted once",pushes.filter(e=>e.kind==="register").length,2);
 const exit=await session.stop(); check("real Pi exit",exit.exitCode,0);
 console.log(JSON.stringify({checks,runRoot:run.root.path,sessionFile:file,pushes,frames:session.frames(),requests:run.capture.requests()},null,2));
} finally { if(session?.running) await session.stop(); panel.stop(true); run.capture.stop(); }

